INSERT INTO public.landing_content(key,value) VALUES('hero_content_v2',jsonb_build_object('title','Seu negócio com site próprio, domínio e agendamento online','subtitle','Receba um site com sua logo, cores e serviços, conectado ao painel de agendamento. Seus clientes agendam pelo endereço do seu negócio, e você organiza os atendimentos no celular ou no computador.')) ON CONFLICT(key) DO UPDATE SET value=coalesce(landing_content.value::jsonb,'{}'::jsonb)||excluded.value::jsonb;
